 now.setDate(weekDays);
 let daysToMinus = now.getDay() + 1;

 now = new Date(new Date().getFullYear(), 0, 1);
 let weelStart = weekDays - daysToMinus;
 let startDate = now.setDate(weelStart);

 now = new Date(new Date().getFullYear(), 0, 1);
