string compoundName = "2-chlorobutane";
string functionalGroup = "chloro";
if (compoundName.Contains(functionalGroup))
{
    int index = compoundName.IndexOf(functionalGroup);
    string prefix = compoundName.Substring(0, index);
    string suffix = compoundName.Substring(index + functionalGroup.Length);
    Console.WriteLine("The functional group " + functionalGroup + " causes a break in the naming of the compound " + compoundName + " between " + prefix + " and " + suffix);
