```rust
use reqwest::blocking::Client;
use serde::{Serialize, Deserialize};

/// Sends a POST request to the specified `uri` with headers and a JSON body.
fn get_transactions_to_approve(uri: &str, body: &str) -> Result<GetTransactionsToApprove, Box<dyn std::error::Error>> {
    let client = Client::new();
    let response = client.post(uri)
        .header("ContentType", "application/json")
        .header("X-IOTA-API-Version", "1")
        .body(body.to_string())
        .send()?;

    // Parse and return the JSON response if successful
    if response.status().is_success() {
        let json_res: GetTransactionsToApprove = response.json()?;
        Ok(json_res)
    } else {
        Err("Request was not successful".into())
    }
}

