grid\_section fullSensor()
{
 return {.x = 0, .y = 0, .width = focusstat\_get\_grid\_width(), .height = focusstat\_get\_grid\_height()};
}

const float cropPosChangeThresholdForRefocus = 0.1; //TODO: Value must be fine tuned according to real test
bool cropIsSimilar(const grid\_section & a, const grid\_section & b, float relativPosChangeLimit)
{
 float relativeX1Change = std::abs(a.x - b.x) / (float) AAA\_GRID\_WIDTH;
 float relativeY1Change = std::abs(a.y - b.y) / (float) AAA\_GRID\_HEIGHT;
 float relativeX2Change = std::abs(a.x + a.width - (b.x + b.width)) / (float) AAA\_GRID\_WIDTH;
 float relativeY2Change = std::abs(a.y + a.height - (b.y + b.height)) / (float) AAA\_GRID\_HEIGHT;

 focus\_logger\_debug\_print(2, "%s : relativ crop position change x1:%f y1:%f and x2:%f y2:%f\n",
 \_\_func\_\_, relativeX1Change, relativeY1Change, relativeX2Change, relativeY2Change);

 return relativeX1Change <= relativPosChangeLimit &&
 relativeY1Change <= relativPosChangeLimit &&
 relativeX2Change <= relativPosChangeLimit &&
 relativeY2Change <= relativPosChangeLimit;
}

bool cropIsSame(const FocusCrop & a, const FocusCrop & b)
{
 return cropIsSimilar(a.statsRegion, b.statsRegion, 0);
}

grid\_section getUpperCropHalf(const grid\_section & grid)
{
 return {.x = grid.x, .y = grid.y, .width = grid.width, .height = grid.height/2};
}

int motorGetPos(const std::string & name)
{
 int fd = ceres\_motor\_open(name.c\_str());
 if (fd < 0) {
 focus\_logger\_debug\_print(1, "Unable to open motor %s!\n", name.c\_str());
 return 0;
 }
 int pos;
 ceres\_motor\_get\_pos(fd, &pos);
 ceres\_motor\_close(fd);
 return pos;
}

void motorSetPos(const std::string & name, int & pos)
{
 int fd = ceres\_motor\_open(name.c\_str());
 if (fd < 0) {
 focus\_logger\_debug\_print(1, "Unable to open motor %s!\n", name.c\_str());
 return;
 }
 int minPos;
 int maxPos;
 ceres\_motor\_get\_range(fd, &minPos, &maxPos);
 pos = std::clamp(pos, minPos, maxPos);
 ceres\_motor\_goto\_pos(fd, pos);
 ceres\_motor\_close(fd);
}

