 roiOnSensor.push\_back({53, 24, 14, 8});

 roiOnSensor.push\_back({ 0, 0, AAA\_GRID\_WIDTH, AAA\_GRID\_HEIGHT});

 return roiOnSensor;
}

grid\_section placeRoiInCrop(grid\_section crop, grid\_section roiOnSensor)
{
 // Slight simplification, ignoring AAA\_GRID\_PIX\_OFST
 float normalized\_x = static\_cast(roiOnSensor.x) / AAA\_GRID\_WIDTH;
 float normalized\_y = static\_cast(roiOnSensor.y) / AAA\_GRID\_HEIGHT;
 float normalized\_width = static\_cast(roiOnSensor.width) / AAA\_GRID\_WIDTH;
 float normalized\_height = static\_cast(roiOnSensor.height) / AAA\_GRID\_HEIGHT;

 // Calculating positions relative to crop, so (0, 0) is top left inside crop
 int start\_x = std::round(crop.width \* normalized\_x);
 int start\_y = std::round(crop.height \* normalized\_y);
 // 'end' is one past
 int end\_x = std::round(crop.width \* (normalized\_x + normalized\_width));
 int end\_y = std::round(crop.height \* (normalized\_y + normalized\_height));

 // Calculating relative to sensor, and clamping inside sensor
 start\_x = std::clamp(start\_x + crop.x, 0, AAA\_GRID\_WIDTH - 1);
 start\_y = std::clamp(start\_y + crop.y, 0, AAA\_GRID\_HEIGHT - 1);
 end\_x = std::clamp(end\_x + crop.x, 1, AAA\_GRID\_WIDTH);
 end\_y = std::clamp(end\_y + crop.y, 1, AAA\_GRID\_HEIGHT);

 return { .x = start\_x, .y = start\_y, .width = end\_x - start\_x, .height = end\_y - start\_y};
}

void applyFixeNbOfRoiInCrop(grid\_section crop, std::vector & roiOnSensor)
{
 std::vector roi\_pattern\_on\_sensor = sensorRois();

 printGridRegions(roi\_pattern\_on\_sensor, 2);

 for (size\_t i = 0; i < roi\_pattern\_on\_sensor.size(); i++) {
 roiOnSensor.push\_back(placeRoiInCrop(crop, roi\_pattern\_on\_sensor[i]));
 }
}

void applyOneRoiInCrop(grid\_section crop, std::vector & roiOnSensor)
{
 int skipped\_hor\_border = crop.height /10; // for focus discard the 10% region around the crop
 int skipped\_ver\_border = crop.width /10;

 roiOnSensor.push\_back({
 .x = crop.x + skipped\_ver\_border,
 .y = crop.y + skipped\_hor\_border,
 .width = crop.width - 2\*skipped\_ver\_border ,
 .height = crop.height - 2\*skipped\_hor\_border});
}

std::vector getRoiInSensor(const grid\_section & crop)
{
 std::vector roiOnSensor;

 // For frames crops smaller than the resulting size of the maximum speakertrack zoom factor,
 if (crop.width < AAA\_GRID\_WIDTH / 2.7){
 focus\_logger\_debug\_print(1, "Make one large focus ROI\n");
 applyOneRoiInCrop(crop, roiOnSensor);
 applyOneRoiInCrop(fullSensor(), roiOnSensor);
 }
 else{
 focus\_logger\_debug\_print(1, "Go for large adaptive sized focus ROIs\n");
 applyFixeNbOfRoiInCrop(crop, roiOnSensor);
 }
 focus\_logger\_debug\_print(1, "Number of focus cells in crop : %d\n", static\_cast(roiOnSensor.size()));
 printGridRegions(roiOnSensor, 2);

 return roiOnSensor;
}

void getRegionFocusValues(uint32\_t \* focusValues, const std::vector & roiOnSensor, unsigned lens)
{
 for (size\_t i = 0; i < roiOnSensor.size(); i++) {
 grid\_section roi\_on\_crop = roiOnSensor[i];
 focusstat data\_sum;
 focusstat\_get\_average(&roi\_on\_crop, &data\_sum);
 focusValues[i] = data\_sum.sensor[lens].low\_res;
 }
}

float numDistances(const std::vector & crops)
{
 int numDist = 0;
 for (const auto & c : crops) {
 numDist += c.distances.size();
 }
 return numDist;
}

float averageDistance(const std::vector & crops)
{
 float sumDist = 0.0;
 int numDist = 0;

 // focus\_logger\_debug\_print(1, "%s, crops: %zu\n", \_\_func\_\_, crops.size());

 for (const auto & c : crops) {
 sumDist = std::accumulate(c.distances.begin(), c.distances.end(), sumDist);
 numDist += c.distances.size();
 }

 if (numDist == 0) {
 return 0.0;
 }
 else {
 return sumDist / numDist;
 }
}

float nearestDistance(const FocusCrop & crop)
{
 if (crop.distances.empty())
 return 0;
 else
 return \*std::min\_element(crop.distances.begin(), crop.distances.end());
}

FocusCrop furthestCrop(const std::vector & crops)
{
 assert(!crops.empty());

 if (numDistances(crops) == 0) {
 // Shouldn't happen in case of Frames
 return crops.front();
 }
 else {
 std::vector furthestPerCrop;
 for (const auto & c : crops) {
 furthestPerCrop.push\_back(\*std::max\_element(c.distances.begin(), c.distances.end()));
 }

 auto furthest = std::max\_element(furthestPerCrop.begin(), furthestPerCrop.end());
 size\_t furthestIndex = furthest - furthestPerCrop.begin();

 return crops[furthestIndex];
 }
}

float furthestDistance(const std::vector & crops)
{
 if (numDistances(crops) == 0)
 // Shouldn't happen in case of Frames, which is the case
 return 0;
 else {
 std::vector furthestPerCrop;
 for (const auto & c : crops)
 furthestPerCrop.push\_back(\*std::max\_element(c.distances.begin(), c.distances.end()));
 return \*std::max\_element(furthestPerCrop.begin(), furthestPerCrop.end());
 }
}

