private const val CITY\_CODE\_LENGTH = 3

/\*\*
 \* Tiny type that encapsulates a city code.
 \* 
 \* City code are 3 characters long and are only valid within Glovo.
 \*/
@JvmInline
value class CityCode(val value: String) {
 init {
 require(value.length == CITY\_CODE\_LENGTH) { "City code with wrong length: $value" }
 }

 companion object {

 fun parse(value: String): Either =
 Either.catch({ InvalidCityCodeError(value, it.message ?: "") }) { CityCode(value) }

 fun isValid(value: String): Boolean = parse(value).isRight()
 }
}

data class InvalidCityCodeError(val input: String, val reason: String) :
 DefaultInvalidInputError("Invalid city code: $reason")

