```cpp
struct MyArray
{
 \_\_declspec(property(get=get\_item, put=set\_item)) int item[];

 int get\_item(int index) {
 // Return the value at the specified index
 return \_items[index];
 }

 void set\_item(int index, int value) {
 // Set the value at the specified index
 \_items[index] = value;
 }

 int \_items[10];
};

int main()
{
 MyArray array;

 // Set the value of the first item in the array
 array.item[0] = 10;

 // Get the value of the first item in the array
 int x = array.item[0];

 return 0;
}
```

```cpp
struct Person
{
 \_\_declspec(property(get=get\_name, put=set\_name)) std::string name;

 std::string get\_name() const {
 return \_name;
 }

 void set\_name(const std::string& value) {
 if (value.empty()) {
 throw std::invalid\_argument("Name cannot be empty");
 }
 \_name = value;
 }

 std::string \_name;
};

int main()
{
 Person person;

 // Set the person's name to "John"
 person.name = "John";

 // The following line will throw an exception because the name is empty
 person.name = "";

 return 0;
}
