// create a new button element
var saveButton = document.createElement('button');
saveButton.innerHTML = 'Save Conversation';

// add a click event listener to the button
saveButton.addEventListener('click', function() {
 // retrieve the current conversation from the page
 var conversation = document.getElementById('conversation').innerText;

 // save the conversation to your S3 bucket
 var bucket = new AWS.S3({params: {Bucket: 'your-bucket-name'}});
 var params = {Key: 'conversation-' + Date.now(), Body: conversation};
 bucket.upload(params, function(err, data) {
 if (err) {
 console.log('Error saving conversation: ', err);
 } else {
 console.log('Conversation saved successfully: ', data);
 }
 });
});

// add the button to the page
document.body.appendChild(saveButton);

